#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int R, C;
    cin >> R >> C;
    vector<string> g(R);
    for (auto& row : g) cin >> row;
    if (g[0][0] == '#' || g[R - 1][C - 1] == '#') { cout << -1 << '\n'; return 0; }
    vector<vector<int>> dist(R, vector<int>(C, -1));
    dist[0][0] = 0;
    queue<pair<int, int>> q;
    q.push({0, 0});
    const int di[4] = {1, -1, 0, 0}, dj[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [i, j] = q.front();
        q.pop();
        for (int k = 0; k < 4; k++) {
            int a = i + di[k], b = j + dj[k];
            if (a >= 0 && a < R && b >= 0 && b < C && g[a][b] == '.' && dist[a][b] < 0) {
                dist[a][b] = dist[i][j] + 1;
                q.push({a, b});
            }
        }
    }
    cout << dist[R - 1][C - 1] << '\n';
    return 0;
}

